{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent increase cap","requirement":"A landlord may not raise rent by more than the lesser of 3% of current rent or 80% of the CPI change each year. The maximum allowable increase is 2.87% from September 1, 2026 through August 31, 2027.","key_value":"2.87% for 2026-09-01 to 2027-08-31; lesser of 3% or 80% of CPI","coverage_conditions":null,"applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":"2026-09-01","citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"2.87 percent is the maximum allowable rent increase for the period of September 1, 2026 through August 31, 2027.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana just cause eviction requirement","requirement":"A landlord must have a valid reason to evict a tenant, such as nonpayment of rent, breaking the lease, or the landlord wanting to move into the property. In certain eviction cases the landlord may have to help pay moving costs.","key_value":null,"coverage_conditions":null,"applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
